import React from 'react';
import { useNavigate } from 'react-router-dom';

export const ACCOUNT_BORDER = 'rgba(255, 255, 255, 0.1)';
export const ACCOUNT_MUTED = '#94a3b8';

function IconOverview(props) {
    return (
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" {...props}>
            <rect x="3" y="3" width="7" height="9" rx="1" />
            <rect x="14" y="3" width="7" height="5" rx="1" />
            <rect x="14" y="12" width="7" height="9" rx="1" />
            <rect x="3" y="16" width="7" height="5" rx="1" />
        </svg>
    );
}

/** نفس فكرة أيقونة الاستمارة في Hero — مستند بخطوط */
function IconFormTemplates(props) {
    return (
        <svg width="18" height="18" viewBox="0 0 64 64" fill="none" aria-hidden {...props}>
            <rect x="12" y="8" width="40" height="48" rx="2" stroke="currentColor" strokeWidth="4" fill="none" strokeLinejoin="round" />
            <line x1="20" y1="22" x2="44" y2="22" stroke="currentColor" strokeWidth="4" strokeLinecap="round" />
            <line x1="20" y1="32" x2="44" y2="32" stroke="currentColor" strokeWidth="4" strokeLinecap="round" />
            <line x1="20" y1="42" x2="36" y2="42" stroke="currentColor" strokeWidth="4" strokeLinecap="round" />
        </svg>
    );
}

function IconGear(props) {
    return (
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" {...props}>
            <circle cx="12" cy="12" r="3" />
            <path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42" />
        </svg>
    );
}

function IconUsers(props) {
    return (
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" {...props}>
            <path d="M17 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2M9 11a4 4 0 100-8 4 4 0 000 8zM23 21v-2a4 4 0 00-3-3.87M16 3.13a4 4 0 010 7.75" />
        </svg>
    );
}

function IconBarChart(props) {
    return (
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" {...props}>
            <path d="M12 20V10M18 20V4M6 20v-4" />
        </svg>
    );
}

function IconWallet(props) {
    return (
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" {...props}>
            <path d="M21 12V7H5a2 2 0 010-4h14v4M3 5v14a2 2 0 002 2h16v-5M18 12a2 2 0 100 4 2 2 0 000-4z" />
        </svg>
    );
}

function IconReceipt(props) {
    return (
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" {...props}>
            <path d="M4 2v20l2-1 2 1 2-1 2 1 2-1 2 1 2-1 2 1V2l-2 1-2-1-2 1-2-1-2 1-2-1-2 1zM16 8H8M16 12H8M10 16H8" />
        </svg>
    );
}

function IconArrowLeft(props) {
    return (
        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden {...props}>
            <path d="M19 12H5M12 19l-7-7 7-7" />
        </svg>
    );
}

const sidebarSections = [
    {
        items: [
            { id: 'overview', label: 'Overview', icon: IconOverview },
            { id: 'templates', label: 'Form templates', icon: IconFormTemplates },
            { id: 'settings', label: 'Settings', icon: IconGear },
        ],
    },
    {
        items: [
            { id: 'members', label: 'Members', icon: IconUsers },
            { id: 'usage', label: 'Usage', icon: IconBarChart },
            { id: 'spending', label: 'Spending', icon: IconWallet },
            { id: 'billing', label: 'Billing & Invoices', icon: IconReceipt },
        ],
    },
];

function routeForNavItem(id) {
    if (id === 'overview') return '/account';
    if (id === 'templates') return '/interview-templates';
    if (id === 'settings') return '/account/settings';
    if (id === 'usage') return '/account/usage';
    if (id === 'spending') return '/account/spending';
    if (id === 'billing') return '/account/billing';
    if (id === 'members') return '/account/members';
    return null;
}

/**
 * @param {object} props
 * @param {string} props.activeId — e.g. 'overview' | 'settings' | 'usage' | 'spending' | 'billing' | 'members'
 * @param {{ to: string, ariaLabel?: string, label?: string } | null | undefined} [props.bottomBack] — footer control; undefined = default /dashboard + aria; null = hide
 */
export function AccountSidebar({ activeId, bottomBack }) {
    const navigate = useNavigate();
    const BORDER = ACCOUNT_BORDER;
    const MUTED = ACCOUNT_MUTED;

    const resolvedBottom =
        bottomBack === undefined
            ? { to: '/dashboard', ariaLabel: 'Back to Dashboard' }
            : bottomBack;

    const handleNavClick = (itemId) => {
        const path = routeForNavItem(itemId);
        if (path) navigate(path);
    };

    const bottomAria =
        resolvedBottom &&
        (resolvedBottom.ariaLabel || resolvedBottom.label || 'Back');

    return (
        <aside
            className="dashboard-card account-sidebar"
            style={{
                width: 260,
                flexShrink: 0,
                position: 'sticky',
                top: 88,
                borderRadius: 8,
                padding: '18px 14px',
                boxSizing: 'border-box',
            }}
        >
            <div
                style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: 12,
                    padding: '8px 10px 16px',
                    borderBottom: `1px solid ${BORDER}`,
                }}
            >
                <div
                    style={{
                        width: 40,
                        height: 40,
                        borderRadius: '50%',
                        background: 'linear-gradient(135deg, #06b6d4, #2563eb)',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        fontWeight: 700,
                        fontSize: 14,
                        color: '#fff',
                    }}
                >
                    AM
                </div>
                <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontWeight: 600, fontSize: 14, lineHeight: 1.3 }}>ali mahmood</div>
                    <span
                        style={{
                            display: 'inline-block',
                            marginTop: 4,
                            fontSize: 11,
                            fontWeight: 600,
                            padding: '2px 8px',
                            borderRadius: 4,
                            background: 'rgba(34, 211, 238, 0.2)',
                            color: '#67e8f9',
                        }}
                    >
                        Pro
                    </span>
                </div>
                <button
                    type="button"
                    aria-label="More"
                    className="btn btn-secondary btn-large account-sidebar-more"
                >
                    <svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor">
                        <circle cx="12" cy="6" r="1.5" />
                        <circle cx="12" cy="12" r="1.5" />
                        <circle cx="12" cy="18" r="1.5" />
                    </svg>
                </button>
            </div>

            <nav style={{ paddingTop: 8 }}>
                {sidebarSections.map((section, si) => (
                    <div key={si}>
                        {si > 0 ? <div style={{ height: 1, background: BORDER, margin: '10px 8px' }} /> : null}
                        <ul style={{ listStyle: 'none', margin: 0, padding: 0 }}>
                            {section.items.map((item) => {
                                const Icon = item.icon;
                                const active = item.id === activeId;
                                return (
                                    <li key={item.id}>
                                        <button
                                            type="button"
                                            className={`btn btn-secondary account-nav-item${
                                                active ? ' account-nav-item--active' : ''
                                            }`}
                                            style={{ marginBottom: 2 }}
                                            onClick={() => handleNavClick(item.id)}
                                        >
                                            <Icon style={{ opacity: active ? 1 : 0.85 }} />
                                            {item.label}
                                        </button>
                                    </li>
                                );
                            })}
                        </ul>
                    </div>
                ))}
            </nav>

            {resolvedBottom ? (
                <div style={{ marginTop: 20, display: 'flex', justifyContent: 'center' }}>
                    <button
                        type="button"
                        onClick={() => navigate(resolvedBottom.to)}
                        className="btn btn-secondary btn-large account-sidebar-cta"
                        aria-label={bottomAria}
                    >
                        <IconArrowLeft />
                    </button>
                </div>
            ) : null}
        </aside>
    );
}

export default AccountSidebar;
