import React from 'react';
import { Link } from 'react-router-dom';
import { useLanguage } from '../contexts/LanguageContext';
import Footer from './Footer';

/**
 * Shell for About, Contact, Privacy, Terms, Data & Security.
 * Content comes from translations; replace keys or wire to CMS/API later.
 */
export default function LegalPageShell({ children, title }) {
    const { t } = useLanguage();

    return (
        <>
            <main className="legal-page-shell">
                <div className="legal-page-container">
                    <nav className="legal-page-breadcrumb" aria-label="Breadcrumb">
                        <Link to="/" className="legal-page-back-link">
                            <span className="legal-page-back-arrow" aria-hidden="true">
                                ←
                            </span>{' '}
                            {t('backToHome')}
                        </Link>
                    </nav>
                    <header className="legal-page-header">
                        <p className="legal-page-meta">{t('legalLastUpdated')}</p>
                        <h1 className="legal-page-title">{title}</h1>
                    </header>
                    <article className="legal-page-article">{children}</article>
                </div>
            </main>
            <Footer />
        </>
    );
}
