import React, { useEffect, useState } from 'react';
import { createPortal } from 'react-dom';

const SHELL_BG = 'linear-gradient(180deg, rgba(30, 41, 59, 0.65) 0%, rgba(15, 23, 42, 0.72) 100%)';
const SHELL_BORDER = '2px solid rgba(255, 255, 255, 0.12)';
const SHELL_SHADOW = '0 12px 40px rgba(0, 0, 0, 0.4)';
const MUTED = '#94a3b8';
const BORDER = 'rgba(255, 255, 255, 0.1)';
const TITLE_GRADIENT = {
    background: 'linear-gradient(135deg, #60A5FA, #3B82F6)',
    WebkitBackgroundClip: 'text',
    WebkitTextFillColor: 'transparent',
    backgroundClip: 'text',
};

function IconCheck(props) {
    return (
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden {...props}>
            <path d="M20 6L9 17l-5-5" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
    );
}

const PLANS = [
    {
        id: 'pro',
        name: 'Pro',
        priceMonthly: 20,
        perUser: false,
        description: 'Solid limits for individual professionals and small squads.',
        features: [
            'Extended limits on Agent',
            'Maximum context windows',
            'Premium models access',
            'Unlimited Tab completions',
        ],
    },
    {
        id: 'pro-plus',
        name: 'Pro+',
        priceMonthly: 60,
        perUser: false,
        description: '3× more usage than Pro with priority support for growing teams.',
        features: [
            'Everything in Pro',
            'Higher Agent limits',
            'Priority support',
            '3× usage vs Pro',
        ],
    },
    {
        id: 'ultra',
        name: 'Ultra',
        priceMonthly: 200,
        perUser: false,
        description: 'Maximum value with the highest limits and dedicated success.',
        features: [
            'Everything in Pro+',
            'Highest throughput and limits',
            '20× usage limits vs Pro',
            'Dedicated success options',
        ],
    },
    {
        id: 'team',
        name: 'Team',
        priceMonthly: 40,
        perUser: true,
        description: 'Collaboration and centralized billing for organizations.',
        features: [
            'Centralized team billing',
            'SAML/OIDC SSO',
            'Admin controls & audit',
            'Shared usage pools',
            'Role-based access',
            'Org-wide policies',
        ],
    },
];

function priceLabel(plan, billing) {
    const base = plan.priceMonthly;
    const monthly = billing === 'annual' ? Math.round(base * 0.8 * 100) / 100 : base;
    const suffix = plan.perUser ? '/user/mo.' : '/mo.';
    return `$${monthly}${suffix}`;
}

/**
 * @param {object} props
 * @param {boolean} props.isOpen
 * @param {() => void} props.onClose
 * @param {string} [props.currentPlanId] — 'pro' | 'pro-plus' | 'ultra' | 'team'
 */
export function AdjustPlanModal({ isOpen, onClose, currentPlanId = 'pro' }) {
    const [billing, setBilling] = useState('monthly');

    useEffect(() => {
        if (!isOpen) return;
        const onKey = (e) => {
            if (e.key === 'Escape') onClose();
        };
        document.addEventListener('keydown', onKey);
        const prev = document.body.style.overflow;
        document.body.style.overflow = 'hidden';
        return () => {
            document.removeEventListener('keydown', onKey);
            document.body.style.overflow = prev;
        };
    }, [isOpen, onClose]);

    if (!isOpen) return null;

    return createPortal(
        <>
            <div
                role="presentation"
                onClick={onClose}
                style={{
                    position: 'fixed',
                    inset: 0,
                    background: 'rgba(0, 0, 0, 0.75)',
                    backdropFilter: 'blur(8px)',
                    WebkitBackdropFilter: 'blur(8px)',
                    zIndex: 10001,
                    animation: 'fadeIn 0.25s ease',
                }}
            />
            <div
                role="dialog"
                aria-modal="true"
                aria-labelledby="adjust-plan-title"
                className="new-interview-modal adjust-plan-modal"
                onClick={(e) => e.stopPropagation()}
                style={{
                    position: 'fixed',
                    top: '50%',
                    left: '50%',
                    transform: 'translate(-50%, -50%)',
                    width: '94%',
                    maxWidth: 1180,
                    maxHeight: '92vh',
                    background: SHELL_BG,
                    backdropFilter: 'blur(24px)',
                    WebkitBackdropFilter: 'blur(24px)',
                    border: SHELL_BORDER,
                    borderRadius: 16,
                    boxShadow: SHELL_SHADOW,
                    zIndex: 10002,
                    padding: '24px 24px 20px',
                    overflow: 'hidden',
                    display: 'flex',
                    flexDirection: 'column',
                    animation: 'modalFadeIn 0.25s ease',
                }}
            >
                <div
                    style={{
                        display: 'flex',
                        alignItems: 'flex-start',
                        justifyContent: 'space-between',
                        gap: 12,
                        marginBottom: 8,
                    }}
                >
                    <div style={{ flex: 1 }} />
                    <div style={{ flex: 1, minWidth: 0, textAlign: 'center' }}>
                        <h2
                            id="adjust-plan-title"
                            style={{
                                margin: 0,
                                fontSize: 22,
                                fontWeight: 700,
                                letterSpacing: '-0.02em',
                                color: '#fff',
                            }}
                        >
                            Adjust your plan
                        </h2>
                        <p style={{ margin: '8px 0 0', fontSize: 14, color: MUTED, fontWeight: 500 }}>
                            Current plan:{' '}
                            <span style={{ color: '#e2e8f0' }}>
                                {PLANS.find((p) => p.id === currentPlanId)?.name ?? 'Pro'}
                            </span>
                        </p>
                    </div>
                    <div style={{ flex: 1, display: 'flex', justifyContent: 'flex-end' }}>
                        <button type="button" className="ni-header-btn-close" onClick={onClose} aria-label="Close">
                            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                                <path d="M18 6L6 18M6 6l12 12" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                            </svg>
                        </button>
                    </div>
                </div>

                {/* Billing toggle */}
                <div
                    style={{
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        flexWrap: 'wrap',
                        gap: 14,
                        marginBottom: 22,
                        marginTop: 4,
                    }}
                >
                    <div
                        role="group"
                        aria-label="Billing period"
                        style={{
                            display: 'inline-flex',
                            padding: 4,
                            borderRadius: 999,
                            background: 'rgba(15, 23, 42, 0.85)',
                            border: `1px solid ${BORDER}`,
                        }}
                    >
                        {['monthly', 'annual'].map((key) => {
                            const active = billing === key;
                            return (
                                <button
                                    key={key}
                                    type="button"
                                    onClick={() => setBilling(key)}
                                    style={{
                                        padding: '8px 18px',
                                        borderRadius: 999,
                                        border: 'none',
                                        cursor: 'pointer',
                                        fontFamily: 'inherit',
                                        fontSize: 13,
                                        fontWeight: 600,
                                        color: active ? '#f8fafc' : MUTED,
                                        background: active ? 'rgba(255, 255, 255, 0.12)' : 'transparent',
                                        transition: 'background 0.2s ease, color 0.2s ease',
                                    }}
                                >
                                    {key === 'monthly' ? 'Monthly' : 'Annual'}
                                </button>
                            );
                        })}
                    </div>
                    <span style={{ fontSize: 13, fontWeight: 600, color: '#34d399' }}>
                        Save 20% when billed annually
                    </span>
                </div>

                {/* Plan cards */}
                <div
                    style={{
                        display: 'grid',
                        gridTemplateColumns: 'repeat(4, minmax(0, 1fr))',
                        gap: 14,
                        overflowY: 'auto',
                        paddingBottom: 8,
                        flex: 1,
                        minHeight: 0,
                    }}
                    className="adjust-plan-modal-grid"
                >
                    {PLANS.map((plan) => {
                        const isCurrent = plan.id === currentPlanId;
                        return (
                            <div
                                key={plan.id}
                                style={{
                                    display: 'flex',
                                    flexDirection: 'column',
                                    minHeight: 420,
                                    padding: '18px 16px',
                                    borderRadius: 12,
                                    background: 'rgba(255, 255, 255, 0.05)',
                                    border: `1px solid ${BORDER}`,
                                    boxShadow: '0 4px 20px rgba(0, 0, 0, 0.2)',
                                }}
                            >
                                <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap', marginBottom: 10 }}>
                                    <span style={{ fontSize: 17, fontWeight: 700, ...TITLE_GRADIENT }}>{plan.name}</span>
                                    {isCurrent ? (
                                        <span
                                            style={{
                                                fontSize: 10,
                                                fontWeight: 700,
                                                textTransform: 'uppercase',
                                                letterSpacing: '0.04em',
                                                padding: '3px 8px',
                                                borderRadius: 6,
                                                background: 'rgba(255, 255, 255, 0.08)',
                                                color: MUTED,
                                                border: `1px solid ${BORDER}`,
                                            }}
                                        >
                                            Current plan
                                        </span>
                                    ) : null}
                                </div>
                                <div style={{ fontSize: 22, fontWeight: 700, color: '#fff', letterSpacing: '-0.02em', marginBottom: 10 }}>
                                    {priceLabel(plan, billing)}
                                </div>
                                <p style={{ margin: '0 0 14px', fontSize: 13, color: MUTED, lineHeight: 1.5, flexShrink: 0 }}>
                                    {plan.description}
                                </p>
                                <ul
                                    style={{
                                        listStyle: 'none',
                                        margin: 0,
                                        padding: 0,
                                        flex: 1,
                                        display: 'flex',
                                        flexDirection: 'column',
                                        gap: 10,
                                    }}
                                >
                                    {plan.features.map((f) => (
                                        <li
                                            key={f}
                                            style={{
                                                display: 'flex',
                                                alignItems: 'flex-start',
                                                gap: 8,
                                                fontSize: 13,
                                                color: '#cbd5e1',
                                                lineHeight: 1.45,
                                            }}
                                        >
                                            <IconCheck style={{ flexShrink: 0, marginTop: 2, color: '#94a3b8' }} />
                                            <span>{f}</span>
                                        </li>
                                    ))}
                                </ul>
                                <div style={{ marginTop: 18, paddingTop: 4 }}>
                                    {isCurrent ? (
                                        <button
                                            type="button"
                                            disabled
                                            style={{
                                                width: '100%',
                                                padding: '10px 14px',
                                                borderRadius: 8,
                                                border: `1px solid ${BORDER}`,
                                                background: 'rgba(15, 23, 42, 0.6)',
                                                color: MUTED,
                                                fontWeight: 600,
                                                fontSize: 14,
                                                cursor: 'default',
                                                fontFamily: 'inherit',
                                            }}
                                        >
                                            Your current plan
                                        </button>
                                    ) : plan.id === 'team' ? (
                                        <button
                                            type="button"
                                            style={{
                                                width: '100%',
                                                padding: '10px 14px',
                                                borderRadius: 8,
                                                border: '1px solid rgba(255, 255, 255, 0.2)',
                                                background: 'rgba(15, 23, 42, 0.55)',
                                                color: '#fff',
                                                fontWeight: 600,
                                                fontSize: 14,
                                                cursor: 'pointer',
                                                fontFamily: 'inherit',
                                            }}
                                        >
                                            Get Teams
                                        </button>
                                    ) : (
                                        <button
                                            type="button"
                                            style={{
                                                width: '100%',
                                                padding: '10px 14px',
                                                borderRadius: 8,
                                                border: 'none',
                                                background: '#ffffff',
                                                color: '#0d0d0d',
                                                fontWeight: 600,
                                                fontSize: 14,
                                                cursor: 'pointer',
                                                fontFamily: 'inherit',
                                            }}
                                        >
                                            Choose plan
                                        </button>
                                    )}
                                </div>
                            </div>
                        );
                    })}
                </div>

                <p
                    style={{
                        margin: '18px 0 0',
                        textAlign: 'center',
                        fontSize: 13,
                        color: MUTED,
                        lineHeight: 1.5,
                    }}
                >
                    Need more capabilities for your business?{' '}
                    <a
                        href="#enterprise"
                        onClick={(e) => e.preventDefault()}
                        style={{
                            color: '#60a5fa',
                            fontWeight: 600,
                            textDecoration: 'none',
                            borderBottom: '1px solid rgba(96, 165, 250, 0.45)',
                        }}
                    >
                        Learn more about our Enterprise plans
                    </a>
                    .
                </p>

                <style>{`
                    @media (max-width: 1100px) {
                        .adjust-plan-modal .adjust-plan-modal-grid {
                            grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
                        }
                    }
                    @media (max-width: 560px) {
                        .adjust-plan-modal .adjust-plan-modal-grid {
                            grid-template-columns: 1fr !important;
                        }
                    }
                `}</style>
            </div>
        </>,
        document.body
    );
}

export default AdjustPlanModal;
