function generateHeatmapData(weeks, days) {
    const total = weeks * days;
    const cells = [];
    for (let i = 0; i < total; i += 1) {
        const col = Math.floor(i / days);
        const progress = col / weeks;
        let level = 0;
        const r = Math.sin(i * 12.9898 + 78.233) * 43758.5453;
        const noise = r - Math.floor(r);
        if (noise > 0.55 + progress * 0.35) level = 1;
        if (noise > 0.72 + progress * 0.2) level = 2;
        if (noise > 0.85 + progress * 0.1) level = 3;
        if (noise > 0.93) level = 4;
        cells.push(level);
    }
    return cells;
}

const MONTH_INITIALS = ['J', 'F', 'M', 'A', 'M', 'J', 'J', 'A', 'S', 'O', 'N', 'D'];

function monthLabelsForWeeks(weeks) {
    const labels = [];
    const now = new Date();
    const start = new Date(now);
    start.setDate(start.getDate() - weeks * 7);
    for (let w = 0; w < weeks; w += 1) {
        const d = new Date(start);
        d.setDate(d.getDate() + w * 7);
        const show = d.getDate() <= 7;
        labels.push(show ? MONTH_INITIALS[d.getMonth()] : '');
    }
    return labels;
}

