import React, { useEffect, useMemo, useRef } from 'react';
import { Link } from 'react-router-dom';
import { useLanguage } from '../contexts/LanguageContext';
import { brandRgba } from '../utils/brandColor';

const SOCIAL_DEFAULTS = {
    facebook: 'https://www.facebook.com/',
    instagram: 'https://www.instagram.com/',
    twitter: 'https://x.com/',
    tiktok: 'https://www.tiktok.com/',
};

/** Accent hex per network — same glass gradient recipe as Account `BrandIconTile` */
const SOCIAL_TILE_ACCENTS = {
    facebook: '#1877F2',
    instagram: '#fc6d26',
    twitter: '#38bdf8',
    tiktok: '#36c5f0',
};

function socialBrandTileStyle(accentHex) {
    return {
        '--footer-tile-a26': brandRgba(accentHex, 0.26),
        '--footer-tile-a08': brandRgba(accentHex, 0.08),
        '--footer-tile-border': brandRgba(accentHex, 0.5),
        '--footer-tile-shadow': brandRgba(accentHex, 0.22),
        '--footer-tile-shadow-hover': brandRgba(accentHex, 0.38),
    };
}

const Footer = () => {
    const { t } = useLanguage();
    const footerTitleRef = useRef(null);

    const socialUrls = useMemo(
        () => ({
            facebook: import.meta.env.VITE_SOCIAL_FACEBOOK_URL || SOCIAL_DEFAULTS.facebook,
            instagram: import.meta.env.VITE_SOCIAL_INSTAGRAM_URL || SOCIAL_DEFAULTS.instagram,
            twitter: import.meta.env.VITE_SOCIAL_TWITTER_URL || SOCIAL_DEFAULTS.twitter,
            tiktok: import.meta.env.VITE_SOCIAL_TIKTOK_URL || SOCIAL_DEFAULTS.tiktok,
        }),
        []
    );

    useEffect(() => {
        if (footerTitleRef.current) {
            const titleElement = footerTitleRef.current;

            if (titleElement.innerHTML && titleElement.innerHTML.includes('evaalo') && !titleElement.innerHTML.includes('evaalo-text-en')) {
                const text = titleElement.textContent || titleElement.innerText;

                const evaaloRegex = /\bevaalo\b/gi;
                if (evaaloRegex.test(text)) {
                    const newHTML = text.replace(evaaloRegex, (match) => {
                        return `<span class="evaalo-text-en">${match}</span>`;
                    });
                    titleElement.innerHTML = newHTML;
                }
            }
        }
    }, [t('companyName')]);

    return (
        <footer className="footer">
            <div className="footer-background">
                <div className="footer-ai-dots">
                    <div className="ai-dot" style={{ left: '10%', top: '20%' }}></div>
                    <div className="ai-dot" style={{ left: '25%', top: '45%' }}></div>
                    <div className="ai-dot" style={{ left: '40%', top: '70%' }}></div>
                    <div className="ai-dot" style={{ left: '60%', top: '30%' }}></div>
                    <div className="ai-dot" style={{ left: '75%', top: '60%' }}></div>
                    <div className="ai-dot" style={{ left: '90%', top: '40%' }}></div>
                </div>
                <svg className="footer-connection-lines" xmlns="http://www.w3.org/2000/svg">
                    <line className="connection-line" x1="10%" y1="20%" x2="25%" y2="45%" />
                    <line className="connection-line" x1="25%" y1="45%" x2="40%" y2="70%" />
                    <line className="connection-line" x1="40%" y1="70%" x2="60%" y2="30%" />
                    <line className="connection-line" x1="60%" y1="30%" x2="75%" y2="60%" />
                    <line className="connection-line" x1="75%" y1="60%" x2="90%" y2="40%" />
                </svg>
            </div>

            <div className="container">
                <div className="footer-main">
                    <div className="footer-brand">
                        <h3 className="footer-brand-title" ref={footerTitleRef}>{t('companyName')}</h3>
                        <p className="footer-brand-description">{t('footerDescription')}</p>
                    </div>

                    <div className="footer-links-grid">
                        <div className="footer-column">
                            <h4 className="footer-column-title">{t('quickLinks')}</h4>
                            <ul className="footer-column-links">
                                <li>
                                    <Link to="/about">{t('aboutUs')}</Link>
                                </li>
                                <li className="footer-social-item">
                                    <nav className="footer-social" aria-label={t('followUs')}>
                                        <a
                                            href={socialUrls.facebook}
                                            className="footer-social-brand-tile"
                                            data-footer-brand-tile="true"
                                            style={socialBrandTileStyle(SOCIAL_TILE_ACCENTS.facebook)}
                                            target="_blank"
                                            rel="noopener noreferrer"
                                            aria-label={t('socialFacebook')}
                                        >
                                            <svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
                                                <path d="M18 2h-3a5 5 0 0 0-5 5v3H7v4h3v8h4v-8h3l1-4h-4V7a1 1 0 0 1 1-1h3z" />
                                            </svg>
                                        </a>
                                        <a
                                            href={socialUrls.instagram}
                                            className="footer-social-brand-tile"
                                            data-footer-brand-tile="true"
                                            style={socialBrandTileStyle(SOCIAL_TILE_ACCENTS.instagram)}
                                            target="_blank"
                                            rel="noopener noreferrer"
                                            aria-label={t('socialInstagram')}
                                        >
                                            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75" aria-hidden="true">
                                                <rect x="3" y="3" width="18" height="18" rx="5" ry="5" />
                                                <circle cx="12" cy="12" r="4" />
                                                <circle cx="17.5" cy="6.5" r="1.25" fill="currentColor" stroke="none" />
                                            </svg>
                                        </a>
                                        <a
                                            href={socialUrls.twitter}
                                            className="footer-social-brand-tile"
                                            data-footer-brand-tile="true"
                                            style={socialBrandTileStyle(SOCIAL_TILE_ACCENTS.twitter)}
                                            target="_blank"
                                            rel="noopener noreferrer"
                                            aria-label={t('socialTwitter')}
                                        >
                                            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.35" strokeLinecap="round" aria-hidden="true">
                                                <path d="M4 4l16 16M20 4L4 20" />
                                            </svg>
                                        </a>
                                        <a
                                            href={socialUrls.tiktok}
                                            className="footer-social-brand-tile"
                                            data-footer-brand-tile="true"
                                            style={socialBrandTileStyle(SOCIAL_TILE_ACCENTS.tiktok)}
                                            target="_blank"
                                            rel="noopener noreferrer"
                                            aria-label={t('socialTiktok')}
                                        >
                                            <svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
                                                <path d="M19.59 6.69a4.83 4.83 0 0 1-3.77-4.25V2h-3.45v13.67a2.89 2.89 0 0 1-5.2 1.74 2.89 2.89 0 0 1 2.31-4.64 2.93 2.93 0 0 1 .88.13V9.4a6.84 6.84 0 0 0-1-.05A6.33 6.33 0 0 0 5 20.1a6.34 6.34 0 0 0 10.86-4.43v-7a8.16 8.16 0 0 0 4.77 1.52v-3.4a4.85 4.85 0 0 1-1-.1z" />
                                            </svg>
                                        </a>
                                    </nav>
                                </li>
                            </ul>
                        </div>

                        <div className="footer-column">
                            <h4 className="footer-column-title">{t('legal')}</h4>
                            <ul className="footer-column-links">
                                <li>
                                    <Link to="/privacy">{t('privacy')}</Link>
                                </li>
                                <li>
                                    <Link to="/terms">{t('terms')}</Link>
                                </li>
                                <li>
                                    <Link to="/data-security">{t('dataSecurity')}</Link>
                                </li>
                            </ul>
                        </div>
                    </div>
                </div>

                <div className="footer-divider"></div>

                <div className="footer-bottom">
                    <p className="footer-copyright">{t('copyright')}</p>
                </div>
            </div>
        </footer>
    );
};

export default Footer;
