import React, { useEffect, useRef, useState } from 'react';
import { useLanguage } from '../contexts/LanguageContext';
import { Swiper, SwiperSlide } from 'swiper/react';
import { Navigation, Pagination } from 'swiper/modules';
import 'swiper/css';
import 'swiper/css/navigation';
import 'swiper/css/pagination';

/** Same sky gradient as main process step titles (.step-title) */
const PROCESS_STAGE_HEADING_STYLE = {
    fontSize: '24px',
    fontWeight: 700,
    marginBottom: '20px',
    background: 'linear-gradient(135deg, #60A5FA, #3B82F6)',
    WebkitBackgroundClip: 'text',
    WebkitTextFillColor: 'transparent',
    backgroundClip: 'text',
    fontFamily: 'inherit',
};

const Process = () => {
    const { t } = useLanguage();
    const processRef = useRef(null);
    
    useEffect(() => {
        // Apply evaalo styling to section title
        const elements = processRef.current?.querySelectorAll('.section-title');
        elements?.forEach(el => {
            // Only process if evaalo exists and is not already wrapped
            if (el.innerHTML && el.innerHTML.includes('evaalo') && !el.innerHTML.includes('evaalo-text-en')) {
                // Replace evaalo with wrapped version, avoiding already wrapped ones
                el.innerHTML = el.innerHTML.replace(/\bevaalo\b/gi, '<span class="evaalo-text-en">$&</span>');
            }
        });
    }, [t]);
    const [isMobile, setIsMobile] = useState(window.innerWidth <= 768);
    const swiperRef = useRef(null);
    const [currentPage, setCurrentPage] = useState(0); // 0 = Process page, 1 = New page
    const [isFlipping, setIsFlipping] = useState(false);
    const [currentStage, setCurrentStage] = useState(0); // 0 = Stage 1, 1 = Stage 2, 2 = Stage 3

    useEffect(() => {
        const handleResize = () => {
            setIsMobile(window.innerWidth <= 768);
        };
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    const steps = [
        {
            number: '01',
            icon: (
                <svg width="40" height="40" viewBox="0 0 40 40" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d="M20 5L25 15H35L27 22L30 32L20 26L10 32L13 22L5 15H15L20 5Z" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                </svg>
            ),
            title: t('step1Title'),
            description: t('step1Description')
        },
        {
            number: '02',
            icon: (
                <svg width="40" height="40" viewBox="0 0 40 40" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d="M35 5H5V35H35V5Z" stroke="currentColor" strokeWidth="2"/>
                    <path d="M10 15H30M10 20H30M10 25H20" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
                </svg>
            ),
            title: t('step2Title'),
            description: t('step2Description')
        },
        {
            number: '03',
            icon: (
                <svg width="40" height="40" viewBox="0 0 40 40" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d="M10 13a5 5 0 007.54.54l3-3a5 5 0 00-7.07-7.07l-1.72 1.71" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
                    <path d="M14 11a5 5 0 00-7.54-.54l-3 3a5 5 0 007.07 7.07l1.71-1.71" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
                </svg>
            ),
            title: t('step3Title'),
            description: t('step3Description')
        },
        {
            number: '04',
            icon: (
                <svg width="40" height="40" viewBox="0 0 40 40" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d="M20 15C22.7614 15 25 12.7614 25 10C25 7.23858 22.7614 5 20 5C17.2386 5 15 7.23858 15 10C15 12.7614 17.2386 15 20 15Z" stroke="currentColor" strokeWidth="2"/>
                    <path d="M10 35V32C10 27.5817 13.5817 24 18 24H22C26.4183 24 30 27.5817 30 32V35" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
                </svg>
            ),
            title: t('step4Title'),
            description: t('step4Description')
        },
        {
            number: '05',
            icon: (
                <svg width="40" height="40" viewBox="0 0 40 40" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d="M35 15L15 35L5 25" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                    <path d="M35 5L20 20" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                </svg>
            ),
            title: t('step5Title'),
            description: t('step5Description')
        }
    ];

    const handlePrev = () => {
        if (currentPage === 1) {
            // Go back to Process page
            setIsFlipping(true);
            setTimeout(() => {
                setCurrentPage(0);
                setIsFlipping(false);
            }, 300);
        } else if (swiperRef.current) {
            swiperRef.current.slidePrev();
        }
    };

    const handleNext = () => {
        if (!isMobile) {
            // On desktop, flip to new page
            setIsFlipping(true);
            setTimeout(() => {
                setCurrentPage(1);
                setCurrentStage(0); // Reset to Stage 1
                setIsFlipping(false);
            }, 300);
        } else if (swiperRef.current) {
            // On mobile, use swiper
            swiperRef.current.slideNext();
        }
    };

    return (
        <section className="process" id="process" ref={processRef}>
            <div className="circuit-lines-pattern"></div>
            <div className="tech-grid-overlay"></div>
            <div className="radial-waves"></div>
            
            <div className="container" style={{ position: 'relative', perspective: '1000px', minHeight: '500px' }}>
                <div
                    style={{
                        position: 'relative',
                        width: '100%',
                        height: '100%',
                        transformStyle: 'preserve-3d',
                        transition: 'transform 0.6s',
                        transform: currentPage === 1 ? 'rotateY(180deg)' : 'rotateY(0deg)'
                    }}
                >
                    {/* Process Page - Front */}
                    <div
                        style={{
                            position: currentPage === 0 ? 'relative' : 'absolute',
                            width: '100%',
                            backfaceVisibility: 'hidden',
                            WebkitBackfaceVisibility: 'hidden',
                            transform: 'rotateY(0deg)',
                            opacity: currentPage === 0 ? 1 : 0,
                            pointerEvents: currentPage === 0 ? 'auto' : 'none'
                        }}
                    >
                        <div className="section-header">
                            <h2 className="section-title">{t('applicationProcess')}</h2>
                            <p className="section-description">{t('processDescription')}</p>
                        </div>
                        
                        <div className="process-steps-wrapper">
                            <button 
                                className="process-nav-btn process-nav-prev" 
                                onClick={handlePrev}
                                aria-label="Previous step"
                            >
                                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                                    <path d="M15 18L9 12L15 6" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                                </svg>
                            </button>
                            
                            {!isMobile ? (
                                <div className="process-steps-container" id="processStepsDesktop">
                                    <div className="process-steps-row process-steps-row-top">
                                        <div className="process-step process-step-first">
                                            <div className="step-number">{steps[0].number}</div>
                                            <div className="step-icon">{steps[0].icon}</div>
                                            <h3 className="step-title">{steps[0].title}</h3>
                                            <p className="step-description">{steps[0].description}</p>
                                        </div>
                                    </div>
                                    <div className="process-steps-row">
                                        {steps.slice(1, 5).map((step, index) => (
                                            <React.Fragment key={index}>
                                                <div className="process-step">
                                                    <div className="step-number">{step.number}</div>
                                                    <div className="step-icon">{step.icon}</div>
                                                    <h3 className="step-title">{step.title}</h3>
                                                    <p className="step-description">{step.description}</p>
                                                </div>
                                                {index < 3 && <div className="process-connector"></div>}
                                            </React.Fragment>
                                        ))}
                                    </div>
                                </div>
                            ) : (
                                <Swiper
                                    modules={[Navigation, Pagination]}
                                    spaceBetween={20}
                                    slidesPerView={1}
                                    pagination={{ 
                                        el: '.process-step-indicators',
                                        clickable: true,
                                        bulletActiveClass: 'swiper-pagination-bullet-active'
                                    }}
                                    onSwiper={(swiper) => {
                                        swiperRef.current = swiper;
                                    }}
                                    className="process-steps-swiper"
                                >
                                    {steps.map((step, index) => (
                                        <SwiperSlide key={index} className="process-step">
                                            <div className="step-number">{step.number}</div>
                                            <div className="step-icon">{step.icon}</div>
                                            <h3 className="step-title">{step.title}</h3>
                                            <p className="step-description">{step.description}</p>
                                        </SwiperSlide>
                                    ))}
                                    <div className="swiper-pagination process-step-indicators"></div>
                                </Swiper>
                            )}
                            
                            <button 
                                className="process-nav-btn process-nav-next" 
                                onClick={handleNext}
                                aria-label="Next step"
                            >
                                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                                    <path d="M9 18L15 12L9 6" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                                </svg>
                            </button>
                        </div>
                    </div>

                    {/* New Page - Back */}
                    <div
                        style={{
                            position: currentPage === 1 ? 'relative' : 'absolute',
                            width: '100%',
                            backfaceVisibility: 'hidden',
                            WebkitBackfaceVisibility: 'hidden',
                            transform: 'rotateY(180deg)',
                            opacity: currentPage === 1 ? 1 : 0,
                            pointerEvents: currentPage === 1 ? 'auto' : 'none'
                        }}
                    >
                        <div className="section-header">
                            <h2 className="section-title" style={{ 
                                background: 'linear-gradient(135deg, #60A5FA, #3B82F6)',
                                WebkitBackgroundClip: 'text',
                                WebkitTextFillColor: 'transparent',
                                backgroundClip: 'text'
                            }}>
                                {t('applicationProcess')}
                            </h2>
                            <p 
                                className="section-subtitle"
                                style={{
                                    fontSize: '18px',
                                    fontWeight: 500,
                                    color: '#64748B',
                                    marginTop: '8px',
                                    marginBottom: '16px',
                                    fontFamily: 'inherit',
                                }}
                            >
                                {t('processSubtitle')}
                            </p>
                        </div>
                        
                        <div className="process-steps-wrapper">
                            <button 
                                className="process-nav-btn process-nav-prev" 
                                onClick={handlePrev}
                                aria-label="Go back"
                            >
                                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                                    <path d="M15 18L9 12L15 6" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                                </svg>
                            </button>
                            
                            <div style={{ 
                                flex: 1,
                                display: 'flex',
                                flexDirection: 'row',
                                gap: '20px',
                                width: '100%',
                                alignItems: 'stretch'
                            }}>
                                {/* Stage 1 Container */}
                                <div
                                    style={{
                                        flex: 1,
                                        backgroundColor: '#ffffff',
                                        borderRadius: '12px',
                                        padding: '40px',
                                        boxShadow: '0 4px 20px rgba(0, 0, 0, 0.1)',
                                        fontFamily: 'inherit',
                                    }}
                                >
                                    <h3 style={PROCESS_STAGE_HEADING_STYLE}>
                                        {t('processStage1Title')}
                                    </h3>
                                    <p style={{
                                        color: '#64748B',
                                        fontSize: '16px',
                                        lineHeight: '1.6',
                                        fontFamily: 'inherit',
                                    }}>
                                        {t('processStage1Description')}
                                    </p>
                                </div>

                                {/* Stage 2 Container */}
                                <div
                                    style={{
                                        flex: 1,
                                        backgroundColor: '#ffffff',
                                        borderRadius: '12px',
                                        padding: '40px',
                                        boxShadow: '0 4px 20px rgba(0, 0, 0, 0.1)',
                                        fontFamily: 'inherit',
                                    }}
                                >
                                    <h3 style={PROCESS_STAGE_HEADING_STYLE}>
                                        {t('processStage2Title')}
                                    </h3>
                                    <p style={{
                                        color: '#64748B',
                                        fontSize: '16px',
                                        lineHeight: '1.6',
                                        fontFamily: 'inherit',
                                    }}>
                                        {t('processStage2Description')}
                                    </p>
                                </div>

                                {/* Stage 3 Container */}
                                <div
                                    style={{
                                        flex: 1,
                                        backgroundColor: '#ffffff',
                                        borderRadius: '12px',
                                        padding: '40px',
                                        boxShadow: '0 4px 20px rgba(0, 0, 0, 0.1)',
                                        fontFamily: 'inherit',
                                    }}
                                >
                                    <h3 style={PROCESS_STAGE_HEADING_STYLE}>
                                        {t('processStage3Title')}
                                    </h3>
                                    <p style={{
                                        color: '#64748B',
                                        fontSize: '16px',
                                        lineHeight: '1.6',
                                        fontFamily: 'inherit',
                                    }}>
                                        {t('processStage3Description')}
                                    </p>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </section>
    );
};

export default Process;
