import React, { useEffect, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import AccountSidebar from '../components/AccountSidebar';
import { brandRgba } from '../utils/brandColor';
import {
    ACCOUNT_GRADIENT_TEXT,
    accountPageH1Style,
    accountSectionLabelStyle,
} from '../utils/accountTypography';
import { useInterviewTemplate } from '../contexts/InterviewTemplateContext';
import '../design-styles.css';

const BORDER = 'rgba(255, 255, 255, 0.1)';
const MUTED = '#94a3b8';
const cardPadding = { padding: '22px 24px' };

/** عينات قوالب — عدّل العناوين والحقول لاحقاً أو اربطها بـ API */
const SAMPLE_FORM_TEMPLATES = [
    {
        id: 'template-standard',
        name: 'Standard application',
        description:
            'Full professional profile: contact, experience, education, skills, and languages. Best for most roles.',
        fieldsCount: 18,
        estMinutes: 12,
        badge: 'Default',
        badgeTone: 'default',
        accent: '#3B82F6',
    },
    {
        id: 'template-technical',
        name: 'Technical & engineering',
        description:
            'Emphasizes stack, certifications, and project depth. Shorter narrative fields, more structured skills.',
        fieldsCount: 22,
        estMinutes: 15,
        badge: 'Recommended',
        badgeTone: 'accent',
        accent: '#22d3ee',
    },
    {
        id: 'template-executive',
        name: 'Executive brief',
        description:
            'Compact leadership-focused layout: impact, team size, and strategic scope. Minimal personal detail.',
        fieldsCount: 12,
        estMinutes: 8,
        badge: 'Fast',
        badgeTone: 'muted',
        accent: '#a78bfa',
    },
    {
        id: 'template-remote',
        name: 'Remote & hybrid',
        description:
            'Adds availability, timezone, and collaboration tools. Ideal for distributed teams.',
        fieldsCount: 20,
        estMinutes: 14,
        badge: 'New',
        badgeTone: 'accent',
        accent: '#10b981',
    },
];

function FormTemplateDocIcon({ color, size = 28 }) {
    return (
        <svg
            width={size}
            height={size}
            viewBox="0 0 64 64"
            fill="none"
            xmlns="http://www.w3.org/2000/svg"
            aria-hidden
            style={{ display: 'block' }}
        >
            <rect x="12" y="8" width="40" height="48" rx="2" stroke={color} strokeWidth="3.5" fill="none" strokeLinejoin="round" />
            <line x1="20" y1="20" x2="44" y2="20" stroke={color} strokeWidth="3.5" strokeLinecap="round" />
            <line x1="20" y1="28" x2="44" y2="28" stroke={color} strokeWidth="3.5" strokeLinecap="round" />
            <line x1="20" y1="36" x2="36" y2="36" stroke={color} strokeWidth="3.5" strokeLinecap="round" />
            <line x1="20" y1="44" x2="40" y2="44" stroke={color} strokeWidth="3.5" strokeLinecap="round" />
        </svg>
    );
}

function BrandIconTile({ accent, children }) {
    return (
        <div
            style={{
                width: 56,
                height: 56,
                borderRadius: 12,
                background: `linear-gradient(145deg, ${brandRgba(accent, 0.26)} 0%, ${brandRgba(accent, 0.08)} 42%, rgba(15, 23, 42, 0.62) 100%)`,
                border: `1px solid ${brandRgba(accent, 0.5)}`,
                boxShadow: `0 8px 24px ${brandRgba(accent, 0.22)}, inset 0 1px 0 rgba(255, 255, 255, 0.14)`,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                flexShrink: 0,
                backdropFilter: 'blur(10px)',
                WebkitBackdropFilter: 'blur(10px)',
            }}
        >
            {children}
        </div>
    );
}

function badgeStyle(tone) {
    if (tone === 'accent') {
        return {
            fontSize: 11,
            fontWeight: 600,
            padding: '3px 10px',
            borderRadius: 6,
            background: 'rgba(34, 211, 238, 0.18)',
            color: '#67e8f9',
            border: '1px solid rgba(34, 211, 238, 0.35)',
        };
    }
    if (tone === 'muted') {
        return {
            fontSize: 11,
            fontWeight: 600,
            padding: '3px 10px',
            borderRadius: 6,
            background: 'rgba(255, 255, 255, 0.08)',
            color: MUTED,
            border: `1px solid ${BORDER}`,
        };
    }
    return {
        fontSize: 11,
        fontWeight: 600,
        padding: '3px 10px',
        borderRadius: 6,
        background: 'rgba(59, 130, 246, 0.2)',
        color: '#93c5fd',
        border: '1px solid rgba(59, 130, 246, 0.35)',
    };
}

const InterviewTemplates = () => {
    const navigate = useNavigate();
    const { templates, setTemplates, selectTemplate, selectedTemplate } = useInterviewTemplate();

    useEffect(() => {
        setTemplates((prev) => (prev.length > 0 ? prev : SAMPLE_FORM_TEMPLATES));
    }, [setTemplates]);

    const mergedList = useMemo(() => {
        const byId = new Map(SAMPLE_FORM_TEMPLATES.map((t) => [t.id, { ...t }]));
        templates.forEach((t) => {
            if (t?.id) {
                const prev = byId.get(t.id) || {};
                byId.set(t.id, {
                    accent: '#3B82F6',
                    fieldsCount: 0,
                    estMinutes: 10,
                    badge: 'Custom',
                    badgeTone: 'muted',
                    ...prev,
                    ...t,
                });
            }
        });
        return Array.from(byId.values());
    }, [templates]);

    const handleUseTemplate = (tpl) => {
        selectTemplate(tpl);
        navigate(`/form?template=${encodeURIComponent(tpl.id)}`);
    };

    return (
        <>
            <div
                className="dashboard-page account-dashboard-page"
                style={{
                    minHeight: '100vh',
                    padding: '70px 20px 40px',
                    background: 'linear-gradient(135deg, #0a0e1a 0%, #1a1f3a 50%, #0d1117 100%)',
                    color: '#ffffff',
                    position: 'relative',
                    fontFamily: '"Inter", system-ui, sans-serif',
                }}
            >
                <div className="design-background">
                    <div className="design-orb-1" />
                    <div className="design-orb-2" />
                    <div className="design-orb-3" />
                </div>

                <div
                    className="account-dashboard-inner"
                    style={{
                        maxWidth: 1400,
                        margin: '0 auto',
                        position: 'relative',
                        zIndex: 1,
                        display: 'flex',
                        gap: 28,
                        alignItems: 'flex-start',
                    }}
                >
                    <AccountSidebar activeId="templates" />

                    <main style={{ flex: 1, minWidth: 0 }}>
                        <header style={{ marginBottom: 28 }}>
                            <h1 style={accountPageH1Style()}>Form templates</h1>
                            <p style={{ margin: '12px 0 0', fontSize: 15, color: MUTED, maxWidth: 560, lineHeight: 1.6 }}>
                                Choose a structure for your application form. Candidates complete the same core fields;
                                each template changes emphasis and optional sections (samples below — replace with your
                                real definitions later).
                            </p>
                        </header>

                        <div style={accountSectionLabelStyle}>Browse templates</div>

                        <div
                            style={{
                                display: 'grid',
                                gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))',
                                gap: 16,
                            }}
                        >
                            {mergedList.map((tpl) => {
                                const isSelected = selectedTemplate?.id === tpl.id;
                                return (
                                    <div
                                        key={tpl.id}
                                        className="dashboard-card"
                                        style={{
                                            ...cardPadding,
                                            display: 'flex',
                                            flexDirection: 'column',
                                            minHeight: 260,
                                            border: isSelected
                                                ? '1px solid rgba(34, 211, 238, 0.55)'
                                                : `1px solid ${BORDER}`,
                                            boxShadow: isSelected
                                                ? '0 0 28px rgba(34, 211, 238, 0.18), inset 0 1px 0 rgba(255,255,255,0.06)'
                                                : undefined,
                                            transition: 'border-color 0.25s ease, box-shadow 0.25s ease',
                                        }}
                                    >
                                        <div style={{ display: 'flex', gap: 14, alignItems: 'flex-start', marginBottom: 14 }}>
                                            <BrandIconTile accent={tpl.accent}>
                                                <FormTemplateDocIcon color={tpl.accent} size={28} />
                                            </BrandIconTile>
                                            <div style={{ flex: 1, minWidth: 0 }}>
                                                <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
                                                    <h2
                                                        style={{
                                                            margin: 0,
                                                            fontSize: 17,
                                                            fontWeight: 700,
                                                            color: '#fff',
                                                            lineHeight: 1.35,
                                                        }}
                                                    >
                                                        {tpl.name}
                                                    </h2>
                                                    <span style={badgeStyle(tpl.badgeTone)}>{tpl.badge}</span>
                                                </div>
                                                <p
                                                    style={{
                                                        margin: '10px 0 0',
                                                        fontSize: 14,
                                                        color: MUTED,
                                                        lineHeight: 1.55,
                                                    }}
                                                >
                                                    {tpl.description}
                                                </p>
                                            </div>
                                        </div>

                                        <div
                                            style={{
                                                display: 'flex',
                                                gap: 16,
                                                fontSize: 12,
                                                color: MUTED,
                                                marginTop: 'auto',
                                                paddingTop: 12,
                                                borderTop: `1px solid ${BORDER}`,
                                            }}
                                        >
                                            <span>
                                                <strong style={{ color: '#e2e8f0' }}>{tpl.fieldsCount}</strong> fields
                                            </span>
                                            <span>
                                                ~<strong style={{ color: '#e2e8f0' }}>{tpl.estMinutes}</strong> min
                                            </span>
                                            <span style={{ fontFamily: 'ui-monospace, monospace', opacity: 0.85 }}>
                                                {tpl.id}
                                            </span>
                                        </div>

                                        <div style={{ display: 'flex', gap: 10, marginTop: 16, flexWrap: 'wrap' }}>
                                            <button
                                                type="button"
                                                className="btn btn-primary btn-large"
                                                onClick={() => handleUseTemplate(tpl)}
                                                style={{ flex: '1 1 140px' }}
                                            >
                                                Use template
                                            </button>
                                            <button
                                                type="button"
                                                className="btn btn-secondary btn-large"
                                                onClick={() => selectTemplate(tpl)}
                                                style={{ flex: '1 1 120px' }}
                                            >
                                                {isSelected ? 'Selected' : 'Set as default'}
                                            </button>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>

                        <div className="dashboard-card" style={{ ...cardPadding, marginTop: 20 }}>
                            <h3 style={{ margin: 0, fontSize: 16, fontWeight: 600, ...ACCOUNT_GRADIENT_TEXT }}>
                                Next steps
                            </h3>
                            <p style={{ margin: '12px 0 0', fontSize: 14, color: MUTED, lineHeight: 1.6 }}>
                                Replace <code style={{ color: '#67e8f9', fontSize: 13 }}>SAMPLE_FORM_TEMPLATES</code> in{' '}
                                <code style={{ color: '#67e8f9', fontSize: 13 }}>InterviewTemplates.jsx</code> with your
                                production definitions, or load them from your API and call{' '}
                                <code style={{ color: '#67e8f9', fontSize: 13 }}>setTemplates</code> when data arrives.
                            </p>
                        </div>
                    </main>
                </div>
            </div>
        </>
    );
};

export default InterviewTemplates;
