import React, { useMemo, useState } from 'react';
import AccountSidebar from '../components/AccountSidebar';
import AccountPageLayout from '../components/AccountPageLayout';
import { accountPageH1Style } from '../utils/accountTypography';

const BORDER = 'rgba(255, 255, 255, 0.1)';
const MUTED = '#94a3b8';

const GRID_COLS = 'minmax(140px,1.3fr) minmax(88px,.85fr) minmax(120px,1.2fr) minmax(72px,.75fr) minmax(72px,.65fr)';

function IconDownload(props) {
    return (
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" {...props}>
            <path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4M7 10l5 5 5-5M12 15V3" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
    );
}

function IconChevronDown(props) {
    return (
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" {...props}>
            <path d="M6 9l6 6 6-6" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
    );
}

const MOCK_ROWS = [
    { date: 'Apr 5, 04:01 PM', type: 'Included', model: 'composer-2-fast', tokens: 537_200, cost: 'Included' },
    { date: 'Apr 5, 03:44 PM', type: 'Included', model: 'composer-2-fast', tokens: 1_624_000, cost: 'Included' },
    { date: 'Apr 5, 03:12 PM', type: 'Included', model: 'gpt-4.1-mini', tokens: 89_400, cost: 'Included' },
    { date: 'Apr 5, 02:58 PM', type: 'Included', model: 'composer-2-fast', tokens: 412_800, cost: 'Included' },
    { date: 'Apr 5, 02:15 PM', type: 'Included', model: 'claude-3.5-sonnet', tokens: 256_000, cost: 'Included' },
    { date: 'Apr 5, 01:02 PM', type: 'Included', model: 'composer-2-fast', tokens: 3_200, cost: 'Included' },
    { date: 'Apr 4, 11:30 PM', type: 'Included', model: 'composer-2-fast', tokens: 912_500, cost: 'Included' },
    { date: 'Apr 4, 09:15 PM', type: 'Included', model: 'gpt-4.1', tokens: 128_900, cost: 'Included' },
    { date: 'Apr 4, 06:22 PM', type: 'Included', model: 'composer-2-fast', tokens: 2_100_000, cost: 'Included' },
    { date: 'Apr 4, 04:01 PM', type: 'Included', model: 'embedding-small', tokens: 44_000, cost: 'Included' },
];

function formatTokens(n) {
    if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`;
    if (n >= 1_000) return `${(n / 1_000).toFixed(1)}K`;
    return String(n);
}

function rowsToCsv(rows) {
    const header = 'Date,Type,Model,Tokens,Cost';
    const lines = rows.map((r) =>
        [
            r.date,
            r.type,
            r.model,
            formatTokens(r.tokens),
            r.cost,
        ]
            .map((cell) => `"${String(cell).replace(/"/g, '""')}"`)
            .join(',')
    );
    return [header, ...lines].join('\n');
}

const AccountUsage = () => {
    const [rangePreset, setRangePreset] = useState('30d');
    const rows = useMemo(() => MOCK_ROWS, []);

    const dateRangeLabel = 'Mar 07 - Apr 05';

    const exportCsv = () => {
        const csv = rowsToCsv(rows);
        const blob = new Blob([csv], { type: 'text/csv;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `usage-export-${new Date().toISOString().slice(0, 10)}.csv`;
        a.click();
        URL.revokeObjectURL(url);
    };

    const segmentBtn = (id, label) => {
        const active = rangePreset === id;
        return (
            <button
                key={id}
                type="button"
                onClick={() => setRangePreset(id)}
                className={`btn btn-secondary account-usage-pill${active ? ' account-usage-pill--on' : ''}`}
            >
                {label}
            </button>
        );
    };

    const usageInjectStyle = `
                @media (max-width: 960px) {
                    .account-dashboard-inner { flex-direction: column !important; }
                    .account-usage-page aside {
                        position: relative !important;
                        top: 0 !important;
                        width: 100% !important;
                    }
                }
            `;

    return (
        <AccountPageLayout pageClass="account-usage-page" injectStyle={usageInjectStyle}>
                <AccountSidebar activeId="usage" />

                <main style={{ flex: 1, minWidth: 0 }}>
                    <h1 style={accountPageH1Style('0 0 24px')}>Usage</h1>

                    <div
                        style={{
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'space-between',
                            flexWrap: 'wrap',
                            gap: 16,
                            marginBottom: 20,
                        }}
                    >
                        <div style={{ display: 'flex', alignItems: 'center', flexWrap: 'wrap', gap: 12 }}>
                            <button type="button" className="btn btn-secondary btn-large account-usage-date">
                                {dateRangeLabel}
                                <IconChevronDown style={{ opacity: 0.7 }} />
                            </button>
                            <div
                                className="account-usage-segment"
                                style={{
                                    display: 'inline-flex',
                                    alignItems: 'center',
                                    padding: 3,
                                    borderRadius: 8,
                                    border: `1px solid ${BORDER}`,
                                    background: 'rgba(15, 23, 42, 0.45)',
                                    gap: 2,
                                }}
                            >
                                {segmentBtn('1d', '1d')}
                                {segmentBtn('7d', '7d')}
                                {segmentBtn('30d', '30d')}
                            </div>
                        </div>
                        <button
                            type="button"
                            onClick={exportCsv}
                            className="btn btn-secondary btn-large account-btn-connect"
                        >
                            <IconDownload />
                            Export CSV
                        </button>
                    </div>

                    <div className="dashboard-card" style={{ padding: 0, overflowX: 'auto' }}>
                        <div style={{ minWidth: 720 }}>
                        <div
                            style={{
                                display: 'grid',
                                gridTemplateColumns: GRID_COLS,
                                gap: 12,
                                padding: '16px 22px 12px',
                                fontSize: 11,
                                color: MUTED,
                                fontWeight: 600,
                                letterSpacing: '0.02em',
                                textTransform: 'uppercase',
                                borderBottom: '1px solid rgba(255,255,255,0.06)',
                            }}
                            className="account-usage-table-header"
                        >
                            <span>Date</span>
                            <span>Type</span>
                            <span>Model</span>
                            <span style={{ textAlign: 'right' }}>Tokens</span>
                            <span style={{ textAlign: 'right' }}>Cost</span>
                        </div>
                        <div style={{ padding: '0 22px 8px' }}>
                            {rows.map((row, i) => (
                                <div
                                    key={i}
                                    style={{
                                        display: 'grid',
                                        gridTemplateColumns: GRID_COLS,
                                        gap: 12,
                                        alignItems: 'center',
                                        padding: '14px 0',
                                        fontSize: 14,
                                        color: '#e8e8e8',
                                        borderTop: i === 0 ? 'none' : '1px solid rgba(255,255,255,0.04)',
                                    }}
                                    className="account-usage-table-row"
                                >
                                    <span style={{ color: '#fff' }}>{row.date}</span>
                                    <span style={{ color: MUTED }}>{row.type}</span>
                                    <span style={{ color: '#e8e8e8', fontFamily: 'ui-monospace, monospace', fontSize: 13 }}>
                                        {row.model}
                                    </span>
                                    <span style={{ textAlign: 'right', color: '#e8e8e8' }}>
                                        {formatTokens(row.tokens)}
                                    </span>
                                    <span style={{ textAlign: 'right', color: MUTED }}>{row.cost}</span>
                                </div>
                            ))}
                        </div>
                        </div>
                    </div>
                </main>
        </AccountPageLayout>
    );
};

export default AccountUsage;
