import React from 'react';
import LegalPageShell from '../components/LegalPageShell';
import { useLanguage } from '../contexts/LanguageContext';

/** Placeholder terms — replace after legal review. */
export default function TermsPage() {
    const { t } = useLanguage();

    return (
        <LegalPageShell title={t('terms')}>
            <p>{t('termsPageP1')}</p>
            <p>{t('termsPageP2')}</p>
            <p>{t('termsPageP3')}</p>
        </LegalPageShell>
    );
}
