import React, { useState, useEffect, useRef } from 'react';
import { useLanguage } from '../contexts/LanguageContext';

const Features = () => {
    const { t } = useLanguage();
    const featuresRef = useRef(null);
    
    // Function to wrap "evaalo" with span for English styling
    const wrapEvaalo = (text) => {
        if (!text) return text;
        return text.replace(/(evaalo)/gi, '<span class="evaalo-text-en">$1</span>');
    };
    
    useEffect(() => {
        // Apply evaalo styling to all section titles and links
        const elements = featuresRef.current?.querySelectorAll('.section-title, .nav-link');
        elements?.forEach(el => {
            // Only process if evaalo exists and is not already wrapped
            if (el.innerHTML && el.innerHTML.includes('evaalo') && !el.innerHTML.includes('evaalo-text-en')) {
                // Replace evaalo with wrapped version, avoiding already wrapped ones
                el.innerHTML = el.innerHTML.replace(/\bevaalo\b/gi, '<span class="evaalo-text-en">$&</span>');
            }
        });
    }, [t]);
    const [expandedCards, setExpandedCards] = useState({});
    const [expandedWhyChooseCards, setExpandedWhyChooseCards] = useState({});
    const visualLanguageIcons = [
        { img: 'icon9-removebg-preview.png', title: t('visualLang1Title'), desc: t('visualLang1Desc') },
        { img: 'icon10-removebg-preview.png', title: t('visualLang2Title'), desc: t('visualLang2Desc') },
        { img: 'icon11-removebg-preview.png', title: t('visualLang3Title'), desc: t('visualLang3Desc'), subtitle: t('visualLang3Subtitle'), useCases: [t('visualLang3UseCase1'), t('visualLang3UseCase2'), t('visualLang3UseCase3'), t('visualLang3UseCase4'), t('visualLang3UseCase5')] },
        { img: 'icon12-removebg-preview.png', title: t('visualLang4Title'), desc: t('visualLang4Desc') },
        { img: 'icon2-removebg-preview.png', title: t('visualLang5Title'), desc: t('visualLang5Desc') },
        { img: 'icon17-removebg-preview.png', title: t('visualLang6Title'), desc: t('visualLang6Desc') },
        { img: 'icon13-removebg-preview.png', title: t('visualLang7Title'), desc: t('visualLang7Desc') },
        { img: 'icon16-removebg-preview.png', title: t('visualLang8Title'), desc: t('visualLang8Desc') }
    ];

    const whyChooseFeatures = [
        { img: 'icon3-removebg-preview.png', title: t('whyChoose1Title'), desc: t('whyChoose1Desc') },
        { img: 'icon14-removebg-preview.png', title: t('whyChoose2Title'), desc: t('whyChoose2Desc') },
        { img: 'icon1-removebg-preview.png', title: t('whyChoose3Title'), desc: t('whyChoose3Desc') },
        { img: 'icon5-removebg-preview.png', title: t('whyChoose4Title'), desc: t('whyChoose4Desc') },
        { img: 'icon15-removebg-preview.png', title: t('whyChoose5Title'), desc: t('whyChoose5Desc') },
        { img: 'icon4-removebg-preview.png', title: t('whyChoose6Title'), desc: t('whyChoose6Desc') },
        { img: 'icon18-removebg-preview.png', title: t('whyChoose7Title'), subtitle: t('whyChoose7Subtitle'), desc: t('whyChoose7Desc') },
        { img: 'icon6-removebg-preview.png', title: t('whyChoose8Title'), subtitle: t('whyChoose8Subtitle'), desc: t('whyChoose8Desc') }
    ];

    return (
        <>
            <section className="features" id="features" ref={featuresRef}>
                <div className="container">
                    <div className="section-header">
                        <h2 className="section-title">{t('visualLanguageTitle')}</h2>
                        <p className="section-description">
                            {t('visualLanguageDescription')}
                        </p>
                    </div>
                    <div className="icon-highlights-grid">
                        {visualLanguageIcons.map((icon, index) => {
                            const isExpanded = expandedCards[index] || false;
                            return (
                                <div 
                                    key={index} 
                                    className={`simple-icon-wrapper ${isExpanded ? 'expanded' : ''}`}
                                    onClick={() => {
                                        if (isExpanded) {
                                            // إذا كان الكارت مفتوحاً، أغلق جميع الكروت
                                            setExpandedCards({});
                                        } else {
                                            // إذا كان الكارت مغلقاً، افتحه فقط وأغلق البقية
                                            setExpandedCards({ [index]: true });
                                        }
                                    }}
                                    style={{ cursor: 'pointer' }}
                                >
                                    <div className="icon-wrapper-inner">
                                        <img src={`/images/${icon.img}`} alt={icon.title} className="simple-icon" />
                                    </div>
                                    <div className="icon-text-content">
                                        <h3 className="icon-label">{icon.title}</h3>
                                        <p 
                                            className="icon-description" 
                                            style={{
                                                maxHeight: isExpanded ? '500px' : '0',
                                                opacity: isExpanded ? 1 : 0,
                                                overflow: 'hidden',
                                                transition: 'max-height 0.3s ease, opacity 0.3s ease, margin 0.3s ease',
                                                margin: isExpanded ? '10px 0 0 0' : '0'
                                            }}
                                        >
                                            {icon.desc}
                                        </p>
                                        {icon.subtitle && (
                                            <p 
                                                className="icon-subtitle" 
                                                style={{
                                                    fontSize: '14px',
                                                    fontWeight: 600,
                                                    color: '#22d3ee',
                                                    marginTop: isExpanded ? '12px' : '0',
                                                    marginBottom: isExpanded ? '8px' : '0',
                                                    maxHeight: isExpanded ? '50px' : '0',
                                                    opacity: isExpanded ? 1 : 0,
                                                    overflow: 'hidden',
                                                    transition: 'max-height 0.3s ease, opacity 0.3s ease, margin 0.3s ease'
                                                }}
                                            >
                                                {icon.subtitle}
                                            </p>
                                        )}
                                        {icon.useCases && (
                                            <ul 
                                                className="icon-use-cases" 
                                                style={{
                                                    listStyle: 'none',
                                                    padding: 0,
                                                    margin: 0,
                                                    maxHeight: isExpanded ? '200px' : '0',
                                                    opacity: isExpanded ? 1 : 0,
                                                    overflow: 'hidden',
                                                    transition: 'max-height 0.3s ease, opacity 0.3s ease, margin 0.3s ease',
                                                    marginTop: isExpanded ? '8px' : '0'
                                                }}
                                            >
                                                {icon.useCases.map((useCase, idx) => (
                                                    <li 
                                                        key={idx}
                                                        style={{
                                                            fontSize: '14px',
                                                            color: '#475569',
                                                            lineHeight: '1.6',
                                                            marginBottom: '4px',
                                                            paddingLeft: '16px',
                                                            position: 'relative'
                                                        }}
                                                    >
                                                        <span style={{ position: 'absolute', left: 0 }}>•</span>
                                                        {useCase}
                                                    </li>
                                                ))}
                                            </ul>
                                        )}
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            </section>

            <section className="features" id="features-2">
                <div className="container">
                    <div className="section-header">
                        <h2 className="section-title">{t('whyChooseTitle')}</h2>
                        <p className="section-description">
                            {t('whyChooseDescription')}
                        </p>
                    </div>
                    <div className="icon-highlights-grid">
                        {whyChooseFeatures.map((feature, index) => (
                            <div 
                                key={index} 
                                className="icon-card"
                            >
                                <div className="icon-card-graphic">
                                    <img src={`/images/${feature.img}`} alt={`Icon ${index + 1}`} className="icon-card-image" />
                                </div>
                                <div className="icon-card-body">
                                    <h3 className="icon-card-title">{feature.title}</h3>
                                    {feature.subtitle && (
                                        <p 
                                            className="icon-card-subtitle" 
                                            style={{
                                                fontSize: '14px',
                                                fontWeight: 600,
                                                color: '#22d3ee',
                                                marginTop: '4px',
                                                marginBottom: '8px'
                                            }}
                                        >
                                            {feature.subtitle}
                                        </p>
                                    )}
                                    <p className="icon-card-text">
                                        {feature.desc}
                                    </p>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </section>
        </>
    );
};

export default Features;
