import React from 'react';
import LegalPageShell from '../components/LegalPageShell';
import { useLanguage } from '../contexts/LanguageContext';

/** Copy from translations — swap for CMS/API when ready. */
export default function AboutPage() {
    const { t } = useLanguage();

    return (
        <LegalPageShell title={t('aboutUs')}>
            <p>{t('aboutPageP1')}</p>
            <p>{t('aboutPageP2')}</p>
            <p>{t('aboutPageP3')}</p>
        </LegalPageShell>
    );
}
