import React from 'react';
import LegalPageShell from '../components/LegalPageShell';
import { useLanguage } from '../contexts/LanguageContext';

/** High-level security overview — extend with SOC/ISO PDFs from app data later. */
export default function DataSecurityPage() {
    const { t } = useLanguage();

    return (
        <LegalPageShell title={t('dataSecurity')}>
            <p>{t('securityPageP1')}</p>
            <p>{t('securityPageP2')}</p>
            <p>{t('securityPageP3')}</p>
        </LegalPageShell>
    );
}
